```
// Constants
const G = 9.81; // acceleration due to gravity in m/s^2
const L = 100; // length of the pendulum in pixels

// Canvas and context
const canvas = document.getElementById('pendulum');
const ctx = canvas.getContext('2d');
canvas.width = 400;
canvas.height = 400;

// Pendulum properties
let theta = 0; // initial angle in radians
let omega = 0; // initial angular velocity in rad/s
let dt = 0.01; // time step in seconds

// Update and draw functions
function update() {
  // Calculate the acceleration of the pendulum
  const alpha = -G/L * Math.sin(theta);

  // Update the angular velocity
  omega += alpha * dt;

  // Update the angle
  theta += omega * dt;
}

function draw() {
  // Clear the canvas
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw the pendulum
  ctx.beginPath();
  ctx.arc(canvas.width/2, canvas.height/2, L, 0, Math.PI*2);
  ctx.moveTo(canvas.width/2 + L*Math.sin(theta), canvas.height/2 - L*Math.cos(theta));
  ctx.lineTo(canvas.width/2 + L*Math.sin(theta+0.1), canvas.height/2 - L*Math.cos(theta+0.1));
  ctx.stroke();

  // Draw the rod
  ctx.beginPath();
  ctx.moveTo(canvas.width/2, canvas.height/2);
  ctx.lineTo(canvas.width/2 + L*Math.sin(theta), canvas.height/2 - L*Math.cos(theta));
  ctx.stroke();

  // Draw the axis
  ctx.beginPath();
  ctx.moveTo(canvas.width/2, canvas.height/2);
  ctx.lineTo(canvas.width/2, canvas.height);
  ctx.stroke();
}

// Main loop
setInterval(() => {
  update();
  draw();
}, 16); // 16ms = 60fps

// User input
document.getElementById('initial-angle').addEventListener('input', (e) => {
  theta = (e.target.value * Math.PI) / 180;
  omega = 0;
});

document.getElementById('release').addEventListener('click', () => {
  omega = 0.1; // initial angular velocity in rad/s
});
```
